<?php
namespace Database\Seeders;
use App\Models\{AttendanceRecord,AttendanceSession,ClassTimetable,School,SchoolClass,Student,Teacher,TeacherClassAssignment,TeacherTimetable,User};
use Illuminate\Database\Seeder; use Illuminate\Support\Facades\Hash;
class DatabaseSeeder extends Seeder {public function run():void {$school=School::create(['name'=>'Zindagi Trust Khatoon-e-Pakistan School','code'=>'ZTKPS','district'=>'Karachi','address'=>'Karachi, Sindh','status'=>'active']);User::create(['school_id'=>$school->id,'name'=>'Sana Ahmed','email'=>'admin@ztams.demo','role'=>'administrator','password'=>Hash::make('demo1234')]);User::create(['name'=>'ZTAMS Chief Executive Officer','email'=>'ceo@ztams.demo','role'=>'ceo','password'=>Hash::make('demo1234')]);$names=['Ayesha','Ali','Fatima','Hamza','Sara','Bilal','Zainab','Usman','Mahnoor','Hassan','Hira','Abdullah','Maryam','Ahmed','Khadija','Rayan','Noor','Ibrahim','Anaya','Danish','Laiba','Saad','Iqra','Arham','Mehwish','Taha','Hooria','Zaid','Areeba','Fahad'];$n=0;foreach([9,10,11,12] as $grade)foreach(['A','B','C'] as $section){$n++;$class=SchoolClass::create(['school_id'=>$school->id,'name'=>"Grade $grade-$section",'grade'=>$grade,'section'=>$section,'academic_year'=>'2026-2027','status'=>'active']);$demo=$grade===10&&$section==='B';$user=User::create(['school_id'=>$school->id,'name'=>$demo?'Ayesha Siddiqui':"Teacher $grade$section",'email'=>$demo?'teacher@ztams.demo':"teacher.$grade$section@ztams.demo",'role'=>'teacher','password'=>Hash::make('demo1234')]);$teacher=Teacher::create(['user_id'=>$user->id,'school_id'=>$school->id,'employee_id'=>'ZT-'.str_pad((string)$n,3,'0',STR_PAD_LEFT),'full_name'=>$user->name,'phone'=>'+92300123'.str_pad((string)$n,4,'0',STR_PAD_LEFT),'status'=>'active']);TeacherClassAssignment::create(['teacher_id'=>$teacher->id,'class_id'=>$class->id,'start_date'=>'2026-08-01','is_current'=>true]);foreach(range(1,30) as $i)Student::create(['school_id'=>$school->id,'class_id'=>$class->id,'student_id'=>sprintf('ZT-%d%s-%02d',$grade,$section,$i),'full_name'=>$names[$i-1].' Khan','parent_name'=>'Parent/Guardian','parent_phone'=>'+92300'.str_pad((string)($n*100+$i),7,'0',STR_PAD_LEFT),'status'=>'active']);foreach(range(1,5) as $slot){$subject=['Mathematics','English','Physics','Chemistry','Urdu'][$slot-1];$time=sprintf('%02d:00:00',7+$slot);$end=sprintf('%02d:00:00',8+$slot);ClassTimetable::create(['class_id'=>$class->id,'day_of_week'=>$slot,'start_time'=>$time,'end_time'=>$end,'subject'=>$subject,'room'=>'Room '.(100+$n),'teacher_id'=>$teacher->id]);TeacherTimetable::create(['teacher_id'=>$teacher->id,'class_id'=>$class->id,'day_of_week'=>$slot,'start_time'=>$time,'end_time'=>$end,'subject'=>$subject,'room'=>'Room '.(100+$n)]);}foreach(range(1,5) as $ago){$s=AttendanceSession::create(['school_id'=>$school->id,'class_id'=>$class->id,'teacher_id'=>$teacher->id,'attendance_date'=>now('Asia/Karachi')->subDays($ago)->toDateString(),'status'=>'locked','submitted_at'=>now()->subDays($ago)->setTime(8,50),'locked_at'=>now()->subDays($ago)->setTime(9,0)]);foreach($class->students as $student)AttendanceRecord::create(['attendance_session_id'=>$s->id,'student_id'=>$student->id,'status'=>$student->id%17===0?'absent':($student->id%13===0?'late':'present')]);}}}}
